from fractions import Fraction

def solve(matrix):
    """Determinant of a square integer matrix via exact Fraction elimination."""
    n = len(matrix)
    if n == 0:
        return 1
    a = [[Fraction(x) for x in row] for row in matrix]
    if len(a[0]) == 0:
        return 1  # determinant of a matrix with no columns (empty product)
    det = Fraction(1)
    for k in range(n):
        pivot = None
        for i in range(k, n):
            if a[i][k] != 0:
                pivot = i
                break
        if pivot is None:
            return 0
        if pivot != k:
            a[k], a[pivot] = a[pivot], a[k]
            det = -det
        det *= a[k][k]
        pk = a[k][k]
        for i in range(k + 1, n):
            f = a[i][k] / pk
            if f:
                for j in range(k + 1, n):
                    a[i][j] -= f * a[k][j]
                a[i][k] = Fraction(0)
    return int(det)

