def solve(n, b):
    """Convert integer n to string representation in base b (2-36)."""
    if b < 2 or b > 36:
        raise ValueError("Base out of range")
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

def solve(words, width):
    """Pack words greedily into lines (single spaces) no longer than width.

    A single word longer than width forms its own line. Empty input -> [].
    """
    lines = []
    current = []
    current_len = 0
    for word in words:
        if not current:
            current = [word]
            current_len = len(word)
        else:
            new_len = current_len + 1 + len(word)
            if new_len <= width:
                current.append(word)
                current_len = new_len
            else:
                lines.append(' '.join(current))
                current = [word]
                current_len = len(word)
    if current:
        lines.append(' '.join(current))
    return lines

