from fractions import Fraction

def solve(matrix):
    """Determinant of a square matrix. Exact Bareiss for integer entries;
    exact Fraction elimination otherwise. Empty matrix -> 1."""
    n = len(matrix)
    if n == 0:
        return 1
    rows = [list(row) for row in matrix]
    if len(rows[0]) == 0:
        return 1  # no columns: empty product
    all_int = all(isinstance(x, int) and not isinstance(x, bool) or isinstance(x, bool)
                  for row in rows for x in row)
    if all_int:
        a = rows
        sign = 1
        prev = 1
        for k in range(n - 1):
            if a[k][k] == 0:
                for i in range(k + 1, n):
                    if a[i][k] != 0:
                        a[k], a[i] = a[i], a[k]
                        sign = -sign
                        break
                else:
                    return 0
            for i in range(k + 1, n):
                for j in range(k + 1, n):
                    a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
                a[i][k] = 0
            prev = a[k][k]
        return sign * a[n - 1][n - 1]
    else:
        a = [[Fraction(x) for x in row] for row in rows]
        det = Fraction(1)
        for k in range(n):
            pivot = None
            for i in range(k, n):
                if a[i][k] != 0:
                    pivot = i
                    break
            if pivot is None:
                return 0
            if pivot != k:
                a[k], a[pivot] = a[pivot], a[k]
                det = -det
            det *= a[k][k]
            pk = a[k][k]
            for i in range(k + 1, n):
                f = a[i][k] / pk
                if f:
                    for j in range(k + 1, n):
                        a[i][j] -= f * a[k][j]
                    a[i][k] = Fraction(0)
        return int(det) if det.denominator == 1 else det

