def solve(line):
    """Parse a single CSV line into fields.

    Fields may be double-quoted; inside quotes, commas are literal and a
    doubled double-quote is one quote character.
    """
    fields = []
    buf = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                buf.append(c)
                i += 1
        else:
            if c == '"':
                in_quotes = True
                i += 1
            elif c == ',':
                fields.append(''.join(buf))
                buf = []
                i += 1
            else:
                buf.append(c)
                i += 1
    fields.append(''.join(buf))
    return fields

def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    Resolves ".", "..", collapses multiple slashes, and removes trailing slash.
    The root '/' is preserved.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components (caused by //) and current directory.
            continue
        if part == '..':
            # Go up one level if possible.
            if stack:
                stack.pop()
        else:
            stack.append(part)
    # Reconstruct the simplified path.
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

