def solve(arr):
    """Flatten a nested list (or tuple) of integers into a flat list preserving order.
    Elements may be integers or further nested lists/tuples. Non‑iterable
    elements are appended directly. Strings are not treated as iterables.
    """
    result = []
    def helper(x):
        # treat list or tuple as a container to flatten
        if isinstance(x, (list, tuple)):
            for item in x:
                helper(item)
        else:
            result.append(x)
    helper(arr)
    return result

