    grid: list of list of ints (0/1). Islands are connected 4-directionally.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # explore neighbors
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj]==1:
