def solve(s: str) -> bool:
    """Validate IPv4 address.
    Rules:
    - Exactly four decimal numbers separated by '.'
    - Each number 0..255 inclusive
    - No leading zeros unless the number is exactly '0'
    - No extra whitespace (string is stripped of surrounding spaces)
    """
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

