def solve(tokens):
    """Evaluate reverse Polish notation with +, -, *, / (truncating division)."""
    ops = {'+', '-', '*', '/'}

    def tdiv(a, b):
        # Integer division truncating toward zero.
        q = a // b
        if q < 0 and q * b != a:
            q += 1
        return q

    stack = []
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:
                stack.append(tdiv(a, b))
        else:
            stack.append(int(tok))
    return stack[-1]

