def solve(n, b):
    """Write integer n in base b (2-36) with digits 0-9 then a-z,
    leading '-' for negatives, '0' for zero."""
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    out = []
    while n:
        out.append(digits[n % b])
        n //= b
    return ('-' if neg else '') + ''.join(reversed(out))

