def solve(grid):
    """Count the number of islands in a 2D grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    The grid may be empty or have rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    if cols == 0:
        return 0
    visited = [[False] * len(row) for row in grid]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] != 1:
                continue
            visited[i][j] = True
            # neighbors
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] == 1:
                dfs(i, j)
                count += 1
    return count

