def solve(grid):
    """Count the number of islands in a binary grid.
    1 indicates land, 0 water. Islands connect orthogonally.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc = x+dr, y+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc]==1:
                    stack.append((nr,nc))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                dfs(i,j)
                count += 1
    return count

